function makePreviewWaves(spec) {
  const labels = spec.labels;
  const requires = spec.requires;
  const completed = new Array(labels.length).fill(false);
  const remaining = new Array(labels.length).fill(true);
  const waves = [];
  let remainingCount = labels.length;

  while (remainingCount > 0) {
    const wave = [];

    for (let i = 0; i < labels.length; i++) {
      if (!remaining[i]) continue;

      let ready = true;
      for (let j = 0; j < labels.length; j++) {
        if (requires[i][j] === 1 && !completed[j]) {
          ready = false;
          break;
        }
      }

      if (ready) wave.push(labels[i]);
    }

    if (wave.length === 0) return null;

    for (let i = 0; i < labels.length; i++) {
      if (remaining[i]) {
        let included = false;
        for (let j = 0; j < wave.length; j++) {
          if (labels[i] === wave[j]) {
            included = true;
            break;
          }
        }
        if (included) {
          remaining[i] = false;
          completed[i] = true;
          remainingCount--;
        }
      }
    }

    waves.push(wave);
  }

  return waves;
}
